async def act(page):
    """
    From the current product editor page (New Product), set Price to 769.99,
    Inventory Qty to 42 and Stock Availability to In Stock, set Size to "uni-size"
    and Color to "Blue", then Save the product. The Save click is the last selector-based
    action because it will navigate away.

    No knowledge-base helper functions are applicable for Magento Admin UI here, so none are used.
    """
    # 1) Prices: open the Prices section (in-page) and set Price
    try:
        await page.get_by_role("link", name="Prices").click()
        await page.wait_for_load_state("networkidle")
    except Exception:
        # If the Prices link isn't clickable or present, continue to attempt direct fill
        pass

    try:
        await page.get_by_role("textbox", name="Price").fill("769.99")
    except Exception:
        try:
            await page.get_by_role("table").get_by_role("row", name=lambda n: n and "Price" in n).get_by_role("textbox").fill("769.99")
        except Exception:
            raise Exception("Could not locate the Price field to set 769.99.")

    # 2) Inventory: open the Inventory section and set Qty + Stock Availability
    try:
        await page.get_by_role("link", name="Inventory").click()
        await page.wait_for_load_state("networkidle")
    except Exception:
        try:
            await page.get_by_role("tab", name="Inventory").click()
            await page.wait_for_load_state("networkidle")
        except Exception:
            # continue to try direct field interactions
            pass

    # Set Qty (try common labels and a table-row fallback)
    qty_set = False
    try:
        await page.get_by_role("textbox", name="Qty").fill("42")
        qty_set = True
    except Exception:
        try:
            await page.get_by_role("textbox", name="Quantity").fill("42")
            qty_set = True
        except Exception:
            try:
                await page.get_by_role("table").get_by_role("row", name=lambda n: n and ("Qty" in n or "Quantity" in n)).get_by_role("textbox").fill("42")
                qty_set = True
            except Exception:
                qty_set = False
    if not qty_set:
        raise Exception("Could not locate Qty/Quantity field to set stock quantity to 42.")

    # Set Stock Availability -> In Stock
    try:
        await page.get_by_role("combobox", name="Stock Availability").select_option(label="In Stock")
    except Exception:
        try:
            await page.get_by_role("combobox", name="Stock Status").select_option(label="In Stock")
        except Exception:
            raise Exception("Could not locate Stock Availability/Stock Status combobox to set 'In Stock'.")

    # 3) Attributes: set Size = uni-size and Color = Blue (best-effort with fallbacks). These are required by the task;
    # raise if not found so the failure is explicit.
    # Size
    size_set = False
    try:
        await page.get_by_role("combobox", name="Size").select_option(label="uni-size")
        size_set = True
    except Exception:
        try:
            await page.get_by_role("combobox", name="Size").select_option(label="Uni-size")
            size_set = True
        except Exception:
            try:
                await page.get_by_role("table").get_by_role("row", name=lambda n: n and "Size" in n).get_by_role("combobox").select_option(label="uni-size")
                size_set = True
            except Exception:
                size_set = False
    if not size_set:
        raise Exception("Could not locate Size combobox to set 'uni-size'.")

    # Color
    color_set = False
    try:
        await page.get_by_role("combobox", name="Color").select_option(label="Blue")
        color_set = True
    except Exception:
        try:
            await page.get_by_role("combobox", name="color").select_option(label="Blue")
            color_set = True
        except Exception:
            try:
                await page.get_by_role("table").get_by_role("row", name=lambda n: n and "Color" in n).get_by_role("combobox").select_option(label="Blue")
                color_set = True
            except Exception:
                color_set = False
    if not color_set:
        raise Exception("Could not locate Color combobox to set 'Blue'.")

    # 4) Save the product - final action (navigates away)
    # Use the Save button shown in the page header. This must be the last selector-based call.
    await page.get_by_role("button", name="Save").click()
    await page.wait_for_load_state("networkidle")

